#!/usr/bin/env python3
"""Compare the LaTeX generated by `Main` with Appendix B of Foundations.pdf.

Usage:
    python3 scripts/compare_appendixB.py results/appendixB.tex Foundations.pdf [--json out.json]

Needs `pdftotext` (poppler-utils) to read the PDF.

For every function f0..fN it checks, after removing layout differences
(whitespace, underscores, backslashes):
  * the definition  fN = λ... matches the thesis text
  * the type        fN::...    matches the thesis text
  * every lemma statement the program proved appears in the thesis section
  * the number of finished proofs (\\done in the output, "Done" in the PDF)

The thesis was typeset from an earlier run, so differences are findings,
not necessarily bugs. Exit status is 0 if everything matches, 1 otherwise.
"""
import json
import re
import subprocess
import sys

ARITY = {
    'variable': 1, 'variableL': 1, 'variableF': 1, 'constructor': 1,
    'app': 2, 'parentesis': 1, 'lambdaR': 2, 'caseR': 2,
    'chainCaseBranchs': 2, 'caseBranch': 2, 'hasType': 2, 'chainVars': 2,
    'affirm': 3,
}


def render(s):
    """Turn the generated TeX macros back into plain text."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\':
            j = i + 1
            if j < n and not s[j].isalpha():
                ch = s[j]
                out.append(' ' if ch in ' ,' else ('' if ch == '\\' else ch))
                i = j + 1
                continue
            k = j
            while k < n and s[k].isalpha():
                k += 1
            name = s[j:k]
            i = k
            if name == 'rightarrow':
                out.append(' → ')
                continue
            arity = ARITY.get(name)
            if arity is None:
                continue
            args = []
            for _ in range(arity):
                while i < n and s[i] == ' ':
                    i += 1
                if i < n and s[i] == '{':
                    depth = 0
                    start = i
                    while i < n:
                        if s[i] == '\\':
                            i += 1
                        elif s[i] == '{':
                            depth += 1
                        elif s[i] == '}':
                            depth -= 1
                            if depth == 0:
                                break
                        i += 1
                    args.append(render(s[start + 1:i]))
                    i += 1
                else:
                    args.append('')
            a = args + [''] * (3 - len(args))
            if name in ('variable', 'variableL', 'variableF', 'constructor'):
                out.append(a[0])
            elif name == 'app':
                out.append(f"{a[0]} {a[1]}")
            elif name == 'parentesis':
                out.append(f"({a[0]})")
            elif name == 'lambdaR':
                out.append(f"λ{a[0]} → {a[1]}")
            elif name == 'caseR':
                out.append(f"case {a[0]} of {{{a[1]}}}")
            elif name == 'chainCaseBranchs':
                out.append(f"{a[0]}; {a[1]}")
            elif name == 'caseBranch':
                out.append(f"{a[0]} → {a[1]}")
            elif name == 'hasType':
                out.append(f"{a[0]}:{a[1]}")
            elif name == 'chainVars':
                out.append(f"{a[0]}, {a[1]}")
            elif name == 'affirm':
                out.append(f"{a[1]} = {a[2]}")
        elif c in '{}$':
            i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)


def norm(s):
    return re.sub(r'[\s_\\]', '', s)


def braces_arg(s, start):
    """Return (content, end_index) of the {...} group starting at s[start]."""
    depth = 0
    i = start
    while i < len(s):
        if s[i] == '\\':
            i += 1
        elif s[i] == '{':
            depth += 1
        elif s[i] == '}':
            depth -= 1
            if depth == 0:
                return s[start + 1:i], i + 1
        i += 1
    return s[start + 1:], len(s)


def parse_generated(path):
    tex = open(path, encoding='utf-8').read()
    funcs = {}
    marks = [m for m in re.finditer(r'\\subsection\{\$\\variable\{(f\d+)\}\s*=\s*', tex)]
    for idx, m in enumerate(marks):
        name = m.group(1)
        end = marks[idx + 1].start() if idx + 1 < len(marks) else len(tex)
        chunk = tex[m.start():end]
        # definition: the subsection argument
        arg, after = braces_arg(chunk, chunk.index('{'))
        body = arg.split('=', 1)
        defn = render(arg[arg.index('=') + 1:] if '=' in arg else arg)
        # type: first $...$ after the subsection
        tm = re.search(r'\$(.*?)\$', chunk[after:], re.S)
        typ = render(tm.group(1)) if tm else ''
        # lemma statements: \subsubsection{...}
        lemmas = []
        for sm in re.finditer(r'\\subsubsection\{', chunk):
            a, _ = braces_arg(chunk, sm.end() - 1)
            lemmas.append(render(a))
        funcs[name] = {
            'def': defn.strip(),
            'type': typ.strip(),
            'lemmas': lemmas,
            'done': len(re.findall(r'\\done', chunk)),
        }
    return funcs


def parse_thesis(pdf):
    text = subprocess.run(['pdftotext', '-layout', pdf, '-'], capture_output=True,
                          text=True, check=True).stdout
    lines = text.splitlines()
    # Appendix B body starts at the last "B.1 First Search" heading.
    start = max(i for i, l in enumerate(lines) if re.match(r'^B\.1\s+First Search', l))
    heads = [(i, re.match(r'^B\.\d+\.\d+\s+(f\d+)\b', l).group(1))
             for i, l in enumerate(lines[start:], start)
             if re.match(r'^B\.\d+\.\d+\s+f\d+\b', l)]
    funcs = {}
    for k, (i, name) in enumerate(heads):
        j = heads[k + 1][0] if k + 1 < len(heads) else len(lines)
        sec = lines[i:j]
        sec_text = '\n'.join(sec)

        def grab(prefix):
            for t, l in enumerate(sec):
                if l.startswith(prefix):
                    buf = [l]
                    for l2 in sec[t + 1:]:
                        if not l2.strip() or re.match(r'^\s*f\d+\s*(::|=)', l2):
                            break
                        buf.append(l2)
                    return ' '.join(x.strip() for x in buf)
            return ''
        d = grab(f'{name} = λ')
        funcs[name] = {
            'def': d.split('=', 1)[1] if d else '',
            'type': grab(f'{name}::').split('::', 1)[1] if grab(f'{name}::') else '',
            'text': sec_text,
            'done': len(re.findall(r'\bDone\b', sec_text)),
        }
    return funcs


def main():
    argv = sys.argv[1:]
    json_out = None
    if '--json' in argv:
        k = argv.index('--json')
        json_out = argv[k + 1] if k + 1 < len(argv) else None
        argv = argv[:k] + argv[k + 2:]
    args = [a for a in argv if not a.startswith('--')]
    if len(args) != 2:
        print(__doc__)
        return 2
    gen = parse_generated(args[0])
    thesis = parse_thesis(args[1])

    def key(n):
        return int(n[1:])
    names = sorted(set(gen) | set(thesis), key=key)
    rows = []
    bad = 0
    for n in names:
        g, t = gen.get(n), thesis.get(n)
        if g is None or t is None:
            rows.append((n, 'MISSING in ' + ('program output' if g is None else 'thesis'), '', '', '', ''))
            bad += 1
            continue
        d_ok = norm(g['def']) == norm(t['def'])
        t_ok = norm(g['type']) == norm(t['type'])
        tnorm = norm(t['text'])
        missing = [l for l in g['lemmas'] if norm(l) not in tnorm]
        l_ok = not missing
        done_ok = g['done'] == t['done']
        ok = d_ok and t_ok and l_ok and done_ok
        bad += 0 if ok else 1
        rows.append((n, 'OK' if ok else 'DIFF',
                     'yes' if d_ok else 'NO', 'yes' if t_ok else 'NO',
                     f"{len(g['lemmas']) - len(missing)}/{len(g['lemmas'])}",
                     f"{g['done']} vs {t['done']}"))
    print('| fn | status | definition | type | lemma statements found in thesis | finished proofs (program vs thesis) |')
    print('|---|---|---|---|---|---|')
    for r in rows:
        print('| ' + ' | '.join(r) + ' |')
    print()
    print(f'{len(rows) - bad}/{len(rows)} functions match completely.')
    if json_out:
        out = json_out
        json.dump({'generated': gen, 'thesis': {k: {kk: vv for kk, vv in v.items() if kk != 'text'}
                                                for k, v in thesis.items()}},
                  open(out, 'w'), ensure_ascii=False, indent=1)
    return 0 if bad == 0 else 1


if __name__ == '__main__':
    sys.exit(main())
